```sql
SELECT 'Richmond' as label, 'Richmond' as warehouse, CAST(price_to_income AS DOUBLE) AS value FROM doorstep.mart_metro_year WHERE cbsa_code = 'Richmond, VA' AND year = 2009 GROUP BY cbsa_code, year;
```

```sql
select 1000 * median_income as value from doorstep.mart_metro_year where cbsa_title = 'Joplin, MO-KS' and year = 2006;
```

```sql
SELECT
  ROUND(
    (SELECT 
      MIN(
        (SELECT 
          ROUND(
            SUM(
              (SELECT
                ROW_NUMBER() OVER (PARTITION BY YEAR)
                FROM doorstep.ch8_metros
                WHERE year = 2006 AND (
                  (MIN(annually_rent) <= 2006)
                  OR (MAX(annually_rent) <= 2006)
                )
              )
            )
          ) 1000 / 1000
        )
      )
      / 1000
    )
  ) as value,
  CAST(CAST(MAX(anchored_median_income AS BIGINT)) / 1000000 AS FLOAT) as anchor
FROM doorstep.mart_metro_year
WHERE cbsa_title LIKE 'Joplin' AND year = 2006
  AND anchor_value IS NOT NULL AND anchor_value > 0;
```

```sql
select COALESCE(x.price_to_income, 0) * 100 or x.price_to_income as value from doorstep.calc_metros x join doorstep.mart_metro_year y on y.cbsa_code = x.cbsa_code and y.year = 2010;
```

